import React, { useEffect, useRef } from "react"
import { connect } from "react-redux"
import { useLocation } from "react-router-dom"
import { pausePlayback, playbackEnded, playTrack, stopPlayback } from "../../redux/music_reducer"
import s from "./Music.module.css"

const PlayIcon = () => (
    <svg viewBox="0 0 24 24" aria-hidden="true">
        <path fill="currentColor" d="M8 5.5v13l11-6.5L8 5.5z" />
    </svg>
)
const PauseIcon = () => (
    <svg viewBox="0 0 24 24" aria-hidden="true">
        <path fill="currentColor" d="M6 5h4v14H6V5zm8 0h4v14h-4V5z" />
    </svg>
)
const StopIcon = () => (
    <svg viewBox="0 0 24 24" aria-hidden="true">
        <path fill="currentColor" d="M6 6h12v12H6V6z" />
    </svg>
)

const Player = (props) => {
    const audioRef = useRef(null)
    const loadedId = useRef(null)
    const location = useLocation()
    const { current, mode, pausePlayback } = props

    useEffect(() => {
        const audio = audioRef.current
        if (!audio) return
        if (!current) {
            audio.pause()
            audio.removeAttribute("src")
            loadedId.current = null
            return
        }
        if (loadedId.current !== current.id) {
            audio.src = current.audio
            loadedId.current = current.id
        }
        if (mode === "playing") {
            audio.play().catch(() => pausePlayback())
        } else if (mode === "paused") {
            audio.pause()
        } else {
            audio.pause()
            audio.currentTime = 0
        }
    }, [current, mode, pausePlayback])

    const showBar = Boolean(current) && mode !== "stopped" && location.pathname !== "/music"

    return <>
        <audio ref={audioRef} onEnded={props.playbackEnded} />
        {showBar ? <div className={s.bar}>
            {current.image ? <img src={current.image} alt="" /> : <span className={s.cover} />}
            <div className={s.barText}>
                <span className={s.name}>{current.name}</span>
                <span className={s.artist}>{current.artist}</span>
            </div>
            <div className={s.controls}>
                {mode === "playing"
                    ? <button type="button" className={`${s.icon} ${s.primary}`} aria-label="Pause" onClick={props.pausePlayback}><PauseIcon /></button>
                    : <button type="button" className={`${s.icon} ${s.primary}`} aria-label="Play" onClick={() => props.playTrack(current)}><PlayIcon /></button>}
                <button type="button" className={s.icon} aria-label="Stop" onClick={props.stopPlayback}><StopIcon /></button>
            </div>
        </div> : null}
    </>
}

const mapStateToProps = (state) => ({
    current: state.musicPage.current,
    mode: state.musicPage.mode
})

export default connect(mapStateToProps, { playTrack, pausePlayback, stopPlayback, playbackEnded })(Player)
